40	interface Props {
41	  renderer: (memo: Memo, options: { compact: boolean }) => ReactElement;
42	  listSort?: (list: Memo[]) => Memo[];
43	  state?: State;
44	  orderBy?: string;
45	  filter?: string;
46	  pageSize?: number;
47	  showCreator?: boolean;
