53	function useAutoFetchWhenNotScrollable({
54	  hasNextPage,
55	  isFetchingNextPage,
56	  memoCount,
57	  onFetchNext,
58	}: {
59	  hasNextPage: boolean | undefined;
60	  isFetchingNextPage: boolean;
61	  memoCount: number;
62	  onFetchNext: () => Promise<unknown>;
63	}) {
64	  const autoFetchTimeoutRef = useRef<number | null>(null);
65	
66	  const isPageScrollable = useCallback(() => {
67	    const documentHeight = Math.max(document.body.scrollHeight, document.documentElement.scrollHeight);
68	    return documentHeight > window.innerHeight + 100;
69	  }, []);
70	
71	  const checkAndFetchIfNeeded = useCallback(async () => {
72	    if (autoFetchTimeoutRef.current) {
73	      clearTimeout(autoFetchTimeoutRef.current);
74	    }
75	
76	    await new Promise((resolve) => setTimeout(resolve, 200));
77	
78	    const shouldFetch = !isPageScrollable() && hasNextPage && !isFetchingNextPage && memoCount > 0;
79	
80	    if (shouldFetch) {
81	      await onFetchNext();
82	
83	      autoFetchTimeoutRef.current = window.setTimeout(() => {
84	        void checkAndFetchIfNeeded();
85	      }, 500);
86	    }
87	  }, [hasNextPage, isFetchingNextPage, memoCount, isPageScrollable, onFetchNext]);
88	
89	  useEffect(() => {
90	    if (!isFetchingNextPage && memoCount > 0) {
91	      void checkAndFetchIfNeeded();
92	    }
93	  }, [memoCount, isFetchingNextPage, checkAndFetchIfNeeded]);
94	
95	  useEffect(() => {
96	    return () => {
97	      if (autoFetchTimeoutRef.current) {
98	        clearTimeout(autoFetchTimeoutRef.current);
99	      }
100	    };
101	  }, []);
102	}
103	
104	const PagedMemoList = (props: Props) => {
105	  const t = useTranslate();
106	  const queryClient = useQueryClient();
107	  const { filters } = useMemoFilterContext();
108	  const { maxColumns, compactMode } = useView();
109	  // maxColumns is a ceiling: 1 = single reading column, 0 = as many as fit. The single
110	  // column renders in normal document flow; anything wider becomes the packed grid.
111	  const multiColumn = maxColumns !== 1;
112	
113	  // Measure the available width: when it only fits one column anyway, render the flow
114	  // layout rather than a degenerate one-column grid (capped tiles, composer-as-tile).
115	  // Only the boolean is stored, so continuous resizes re-render nothing until the
116	  // one-column threshold is actually crossed.
117	  const layoutMeasureRef = useRef<HTMLDivElement>(null);
118	  const [fitsGridWidth, setFitsGridWidth] = useState<boolean | undefined>(undefined);
119	  useLayoutEffect(() => {
120	    const el = layoutMeasureRef.current;
121	    if (!el) return;
122	    const apply = (nextWidth: number) => setFitsGridWidth(columnCountForWidth(nextWidth) >= 2);
123	    apply(el.clientWidth);
124	    if (typeof ResizeObserver === "undefined") return;
125	    const observer = new ResizeObserver((entries) => apply(entries[0]?.contentRect.width ?? el.clientWidth));
126	    observer.observe(el);
127	    return () => observer.disconnect();
128	  }, []);
129	  const useGrid = multiColumn && (fitsGridWidth ?? true);
130	  // Grid tiles are always bounded/compact; the narrow-width fallback behaves exactly like
131	  // maxColumns = 1, so it respects the user's own compact setting. Centralized here so the
132	  // pages don't each repeat the policy.
133	  const effectiveCompact = compactMode || useGrid;
134	
135	  const showMemoEditor = props.showMemoEditor ?? false;
136	  const defaultCreateTime = useMemo(() => deriveDefaultCreateTimeFromFilters(filters), [filters]);
137	
138	  const { data, fetchNextPage, hasNextPage, isFetchingNextPage, isLoading } = useInfiniteMemos(
139	    {
140	      state: props.state || State.NORMAL,
141	      orderBy: props.orderBy || "create_time desc",
142	      filter: props.filter,
143	      pageSize: props.pageSize || DEFAULT_LIST_MEMOS_PAGE_SIZE,
144	    },
145	    { enabled: props.enabled ?? true },
146	  );
147	
148	  // Only show the spinner once loading exceeds the delay, so fast loads don't flash it.
149	  const showLoader = useDelayedFlag(isLoading, LOADING_INDICATOR_DELAY_MS);
150	
151	  // Flatten pages into a single array of memos
152	  const memos = useMemo(() => data?.pages.flatMap((page) => page.memos) || [], [data]);
153	
154	  // Apply custom sorting if provided, otherwise use memos directly, then hoist
155	  // a freshly created memo to the very top so it stays visible above pins.
156	  const { newMemoName } = useNewMemo();
157	  const sortedMemoList = useMemo(() => {
158	    const sorted = props.listSort ? props.listSort(memos) : memos;
159	    return hoistMemoToFront(sorted, newMemoName);
160	  }, [memos, props.listSort, newMemoName]);
161	
162	  // Prefetch creators when new data arrives to improve performance
163	  useEffect(() => {
164	    if (!data?.pages || !props.showCreator) return;
165	
166	    const lastPage = data.pages[data.pages.length - 1];
167	    if (!lastPage?.memos) return;
168	
169	    const uniqueCreators = Array.from(new Set(lastPage.memos.map((memo) => memo.creator)));
170	    for (const creator of uniqueCreators) {
171	      void queryClient.prefetchQuery({
172	        queryKey: userKeys.detail(creator),
173	        queryFn: async () => {
174	          const user = await userServiceClient.getUser({ name: creator });
175	          return user;
176	        },
177	        staleTime: 1000 * 60 * 5,
178	      });
179	    }
180	  }, [data?.pages, props.showCreator, queryClient]);
181	
182	  // Auto-fetch hook: fetches more content when page isn't scrollable
183	  useAutoFetchWhenNotScrollable({
184	    hasNextPage,
185	    isFetchingNextPage,
186	    memoCount: sortedMemoList.length,
187	    onFetchNext: fetchNextPage,
188	  });
189	
190	  // Infinite scroll: fetch more when user scrolls near bottom
191	  useEffect(() => {
192	    if (!hasNextPage) return;
193	
194	    const handleScroll = () => {
195	      const nearBottom = window.innerHeight + window.scrollY >= document.body.offsetHeight - 300;
196	      if (nearBottom && !isFetchingNextPage) {
197	        fetchNextPage();
198	      }
199	    };
200	
201	    window.addEventListener("scroll", handleScroll);
202	    return () => window.removeEventListener("scroll", handleScroll);
203	  }, [hasNextPage, isFetchingNextPage, fetchNextPage]);
204	
205	  // In the grid the leading stack owns all spacing (GRID_GAP), so the composer carries
206	  // its own bottom margin only in the flow layout.
207	  const memoEditor = showMemoEditor ? (
208	    <MemoEditor
209	      className={useGrid ? undefined : "mb-2"}
210	      cacheKey="home-memo-editor"
211	      placeholder={t("editor.any-thoughts")}
212	      defaultCreateTime={defaultCreateTime}
213	    />
214	  ) : null;
215	
216	  // A freshly created memo is hoisted to the front; pin it to the top of column one so it
217	  // appears right under the composer instead of dropping into a random (shortest) column.
218	  const firstMemo = sortedMemoList[0];
219	  const priorityKey = newMemoName && firstMemo?.name === newMemoName ? getMemoKey(firstMemo) : undefined;
220	
221	  // Stable reference so MentionResolutionProvider's memo (keyed on the array) actually holds.
222	  const contents = useMemo(() => sortedMemoList.map((memo) => memo.content), [sortedMemoList]);
223	
224	  const emptyPlaceholder =
225	    !isFetchingNextPage && !hasNextPage && sortedMemoList.length === 0 ? (
226	      <Placeholder variant="empty" message={t("message.no-data")} className="w-full" />
227	    ) : null;
228	
229	  // Column one is the action column: the composer and any active filters head it, and the
230	  // empty state follows them. The newest memo also lands directly beneath them (priorityKey
231	  // above). Every vertical seam inside the stack uses GRID_GAP so y-spacing matches the
232	  // grid's x-spacing exactly.
233	  const hasFilters = filters.length > 0;
234	  const gridLeading =
235	    memoEditor || hasFilters || emptyPlaceholder ? (
